import fs from "node:fs"; import path from "node:path"; import ts from "typescript"; import crypto from "node:crypto";
const doc=fs.readFileSync("docs/design/admission-use-lifecycle.md","utf8");
const peer=fs.readFileSync("docs/design/direct-peer-send.md","utf8");
const blocks=s=>[...s.matchAll(/\x60{3}ts\n([\s\S]*?)\n\x60{3}/g)].map(m=>m[1]);
const association=blocks(peer).find(b=>b.includes("type PeerAuthorizationAssociation ="));
if(!association)throw new Error("association declaration not found");
const prelude='import type {NodeId,SessionId,ClockPort} from "@agp/core";\nimport type {PeerTransportPort,TransportRef,TransportListenOptions,TransportAcquisitionOptions,TransportListenerPort,TransportChannelPort} from "@agp/transport";\n';
const checks=[
'declare const ordinaryTransport: PeerTransportPort;',
'declare const admissionFactory: AdmissionAcquisitionFactory;',
'declare const sessionIdentity: AdmissionSessionIdentity;',
'const ordinaryChoice: NodeAcquisitionDependencies = {transport: ordinaryTransport};',
'const admissionChoice: NodeAcquisitionDependencies = {createAdmissionAcquisition: admissionFactory};',
'const closedBeforeAdmission: AdmissionUseSnapshot = {state:"terminal", reachedEstablished:false};',
'const closedAfterEstablishment: AdmissionUseSnapshot = {state:"terminal", reachedEstablished:true, admittedSession:sessionIdentity};',
'// @ts-expect-error Acquisition dependency branches are mutually exclusive.',
'const duplicateChoice: NodeAcquisitionDependencies = {transport: ordinaryTransport, createAdmissionAcquisition: admissionFactory};',
'// @ts-expect-error A plain object is not a sealed handoff.',
'const inventedHandoff: AdmissionChannelHandoff = {};',
'// @ts-expect-error Established history requires an admitted identity.',
'const inventedEstablishment: AdmissionUseSnapshot = {state:"terminal", reachedEstablished:true};',
'// @ts-expect-error Pending state cannot carry a committed session.',
'const inventedPendingIdentity: AdmissionUseSnapshot = {state:"pending", session:sessionIdentity};',
'declare const admissionUse: AdmissionUseReservation;',
'// @ts-expect-error The observation view cannot be reassigned.',
'admissionUse.lifecycle = admissionUse.lifecycle;',
'// @ts-expect-error Enabled admission configuration cannot omit its finite work bound.',
'const incompleteLimits: AdmissionUseConfig = {acquisitionTimeoutMs:1,establishmentTimeoutMs:1,maxPendingUses:1};'
].join("\n");
const virtualPath=path.resolve("admission-acquisition-proposal-typecheck.mts");
const additionalChecks="declare const redemptionClock: ClockPort;\ndeclare const redemptionCapability: AdmissionUseRedemption;\nconst redemptionAuthorization: AdmissionRedemptionAuthorization = {clock:redemptionClock,validBeforeMonotonicMs:1};\nconst proposedRecordedResult: AdmissionRedemptionResult = redemptionCapability.recordAdmissionRedemption(\"type-check-only\", redemptionAuthorization);\n// @ts-expect-error A redemption requires its issuer authorization limit.\nredemptionCapability.recordAdmissionRedemption(\"type-check-only\");\n// @ts-expect-error A numeric limit without the exact clock witness is insufficient.\nconst missingRedemptionClock: AdmissionRedemptionAuthorization = {validBeforeMonotonicMs:1};\n// @ts-expect-error The declared authorization limit is numeric, without coercion.\nconst invalidRedemptionLimit: AdmissionRedemptionAuthorization = {clock:redemptionClock,validBeforeMonotonicMs:\"1\"};\n// @ts-expect-error The authorization limit is immutable to its consumer.\nredemptionAuthorization.validBeforeMonotonicMs = 2;";
const source=prelude+association+"\n"+blocks(doc).join("\n")+"\n"+checks+"\n"+additionalChecks;
const options={noEmit:true,strict:true,noUncheckedIndexedAccess:true,exactOptionalPropertyTypes:true,target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.NodeNext,moduleResolution:ts.ModuleResolutionKind.NodeNext,types:["node"]};
const host=ts.createCompilerHost(options);
const priorGet=host.getSourceFile.bind(host), priorRead=host.readFile.bind(host), priorExists=host.fileExists.bind(host);
host.getSourceFile=(f,l,onError,newFile)=>path.resolve(f)===virtualPath ? ts.createSourceFile(f,source,l,true,ts.ScriptKind.TS):priorGet(f,l,onError,newFile);
host.readFile=f=>path.resolve(f)===virtualPath ? source:priorRead(f);
host.fileExists=f=>path.resolve(f)===virtualPath || priorExists(f);
host.writeFile=()=>{throw new Error("noEmit check attempted a write");};
const program=ts.createProgram([virtualPath],options,host);
const diagnostics=ts.getPreEmitDiagnostics(program);
const formatted=ts.formatDiagnostics(diagnostics,{getCurrentDirectory:()=>process.cwd(),getCanonicalFileName:f=>f,getNewLine:()=>"\n"});
console.log(JSON.stringify({typescript:ts.version,diagnosticCount:diagnostics.length,diagnostics:formatted,documentBlocks:blocks(doc).length,expectedTypeErrors:10,documentSha256:crypto.createHash("sha256").update(doc).digest("hex"),scope:"In-memory compile-only coherence of proposal declarations plus ten rejected shapes; existing primitive contracts imported, proposed APIs not imported from actual packages; no runtime behavior or compatibility assurance."},null,2));
if(diagnostics.length)process.exitCode=1;
