node --input-type=module <<'NODE'
import assert from "node:assert/strict"; import fs from "node:fs"; import path from "node:path";
const files=["docs/design/admission-use-lifecycle.md","docs/BOARD.md","docs/VERIFICATION.md"];
const slug=s=>s.trim().toLowerCase().replace(/<[^>]*>/gu,"").replace(/[\x60*_~]/gu,"").replace(/[.,:;!?()[\]{}'"\\/|<>@#$%^&+=]/gu,"").replace(/\s/gu,"-");
function headings(source){const seen=new Map(),out=new Set();for(const line of source.split(/\r?\n/u)){const m=/^#{1,6}\s+(.+?)\s*$/u.exec(line);if(!m)continue;const b=slug(m[1]),n=seen.get(b)??0;seen.set(b,n+1);out.add(n===0?b:b+"-"+n);}return out;}
const bad=[],counts={},cache=new Map();let total=0;
for(const file of files){const source=fs.readFileSync(file,"utf8");counts[file]=0;assert(!/[^\x00-\x7f]/u.test(source),file+" non-ASCII");
for(const m of source.matchAll(/\]\(([^)\s#]*)(#[^)\s]*)?\)/gu)){const ref=m[1],fragment=m[2];if(/^(?:https?:|mailto:)/u.test(ref))continue;total++;counts[file]++;const target=ref?path.resolve(path.dirname(path.resolve(file)),ref):path.resolve(file);if(!fs.existsSync(target)){bad.push({file,ref,error:"target missing"});continue;}if(fragment&&target.endsWith(".md")){if(!cache.has(target))cache.set(target,headings(fs.readFileSync(target,"utf8")));if(!cache.get(target).has(fragment.slice(1)))bad.push({file,ref:ref+fragment,error:"anchor missing"});}}
}
const draft=fs.readFileSync(files[0],"utf8");
assert(draft.startsWith("# Admission use lifecycle proposal\n\nStatus: amended producer API proposal"));
assert.equal((draft.match(/^## /gmu)||[]).length,10);
assert(!draft.split("\n").some(line=>/[ \t]+$/u.test(line)));
assert.deepEqual(bad,[]);
let fenced=false,tableWidth;
for(const line of draft.split("\n")){if(line.startsWith("\x60\x60\x60")){fenced=!fenced;continue;}if(fenced)continue;if(line.startsWith("|")){const width=line.split("|").length;if(tableWidth===undefined)tableWidth=width;assert.equal(width,tableWidth,"inconsistent table columns: "+line);}else tableWidth=undefined;}
console.log(JSON.stringify({pass:true,totalLocalLinks:total,byFile:counts,bad,scope:"Absolute-aware file/anchor integrity for changed Markdown, draft structure/ASCII/whitespace/table columns; supplements but does not replace tracked-link test."},null,2));
